/// <summary>
/// Defines an ordered chain of item identity sources for the mobile app display line. The
/// <c>ProfileVersion</c> counter increments on every header or line change so cached
/// resolutions can detect stale entries.
/// </summary>
public class AAXWHSItemIdentityProfile extends common
{
}

Method.Source:
/// <summary>
/// Finds the profile with the specified profile id.
/// </summary>
/// <param name = "_profileId">The profile id.</param>
/// <param name = "_forUpdate">True to select the record for update.</param>
/// <returns>The profile record, or an empty buffer when none exists.</returns>
public static AAXWHSItemIdentityProfile find(AAXWHSItemIdentityProfileId _profileId, boolean _forUpdate = false)
{
    AAXWHSItemIdentityProfile profile;

    if (_profileId)
    {
        profile.selectForUpdate(_forUpdate);

        select firstonly profile
            where profile.ProfileId == _profileId;
    }

    return profile;
}

/// <summary>
/// Indicates whether a profile with the specified profile id exists.
/// </summary>
/// <param name = "_profileId">The profile id.</param>
/// <returns>True if a matching profile exists.</returns>
public static boolean exist(AAXWHSItemIdentityProfileId _profileId)
{
    return _profileId != ''
        && (select firstonly RecId from aaxWHSItemIdentityProfile
            where aaxWHSItemIdentityProfile.ProfileId == _profileId).RecId != 0;
}

/// <summary>
/// Increments the version counter of the specified profile so cached resolutions built
/// from it become stale.
/// </summary>
/// <param name = "_profileId">The profile id.</param>
public static void bumpVersion(AAXWHSItemIdentityProfileId _profileId)
{
    AAXWHSItemIdentityProfile profile;

    ttsbegin;

    select forupdate firstonly profile
        where profile.ProfileId == _profileId;

    if (profile)
    {
        profile.ProfileVersion++;

        // Skip the bump in update()
        profile.doUpdate();
    }

    ttscommit;
}

/// <summary>
/// Initializes a new profile with version 1.
/// </summary>
public void initValue()
{
    super();

    this.ProfileVersion = 1;
    this.Separator      = ' | ';
}

/// <summary>
/// Updates the profile and increments its version.
/// </summary>
public void update()
{
    this.ProfileVersion++;

    super();
}
